SELECT invn_id ,(select brand_name from brand B, prdct P where B.brand_id = P.brand_id AND P.prdct_id = I.prdct_id)brandName ,(select B.brand_id from brand B, prdct P where B.brand_id = P.brand_id AND P.prdct_id = I.prdct_id)brandId ,(select prdct_name from prdct where prdct_id = I.prdct_id)prdctName ,(select prdct_id from prdct where prdct_id = I.prdct_id)prdctId ,(select img_path from still_img where prdct_id = I.prdct_id)imgPath ,(select server_url from file_server where isdefault=1)urlStr ,datetime
FROM invn I WHERE I.shop_id = ${shopId}
AND (select B.brand_id from brand B, prdct P where B.brand_id = P.brand_id AND P.prdct_id = I.prdct_id) = #{brandId}
AND (select prdct_name from prdct where prdct_id = I.prdct_id) LIKE CONCAT ("%", #{prdctName} ,"%")

